// Metaballs: eight blobby spheres that melt into each other where they meet, drawn as
// mirrors reflecting a panorama. iTexture0 is an equirectangular photo, also shown as an
// inset at the top right. On the timeline, iFloat0 turns the camera around the balls and
// iFloat1 pushes the balls apart, from all in one place to spread out, and back.
// Based on https://www.shadertoy.com/view/4dj3zV
#define cameraTurn iFloat0
#define spread iFloat1
#define PI 3.14159265359
#define NUM_BALLS 8

// Pseudo-random numbers made from one input: three of them, or one.
vec3 hash31(float p) {
  vec3 p3 = fract(vec3(p) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.xxy + p3.yzz) * p3.zyx);
}

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

// A 2D rotation, used to turn a pair of coordinates such as xz.
mat2 rotate(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat2(c, s, -s, c);
}

// Each ball's centre (xyz) and strength (w).
vec4 balls[NUM_BALLS];

// The metaball field. Each ball adds strength / distance², and the surface is where the
// total reaches 1, so this is negative inside the blobs and positive outside.
float field(vec3 p) {
  float value = 0.0;
  for (int i = 0; i < NUM_BALLS; i++) {
    vec3 d = p - balls[i].xyz;
    value += balls[i].w / dot(d, d);
  }
  return 1.0 - value;
}

// The gradient of field(), worked out by hand. It points out of the surface, so once
// normalised it is the surface normal.
vec3 fieldGradient(vec3 p) {
  vec3 value = vec3(0.0);
  for (int i = 0; i < NUM_BALLS; i++) {
    vec3 d = p - balls[i].xyz;
    float d2 = dot(d, d);
    value += 2.0 * balls[i].w * d / (d2 * d2);
  }
  return value;
}

// The photo's colour in direction dir: the angle around picks x, the angle up picks y.
vec3 panorama(vec3 dir) {
  dir = normalize(dir);
  vec2 uv = vec2(0.5 + atan(dir.x, dir.z) / (2.0 * PI), 1.0 - acos(dir.y) / PI);
  return texture(iTexture0, uv).rgb;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Place the balls: each gets a random direction and strength, and spread sets how far out they sit.
  for (int i = 0; i < NUM_BALLS; i++) {
    vec3 centre = spread * 7.0 * (hash31(1.20742 * float(i)) - 0.5);
    balls[i] = vec4(centre, 5.0 * hash11(2.0 * float(i)));
  }

  // The camera sits back from the balls and turns around them by cameraTurn half-turns.
  float angle = PI * cameraTurn;
  vec3 camera = vec3(0.0, 2.0, 20.0);
  camera.xz = rotate(angle) * camera.xz;

  // The ray through this pixel: a narrow view, nudged off-centre and tilted down a little.
  vec2 ndc = 2.0 * fragCoord / iResolution - 1.0 + vec2(0.27, 0.3);
  vec3 ray = normalize(vec3(0.49586 * ndc, -1.0));
  ray.zy = rotate(0.2) * ray.zy;
  ray.xz = rotate(angle) * ray.xz;

  // Rays that miss see a dark gradient.
  vec3 color = mix(vec3(0.128, 0.113, 0.135), vec3(0.270, 0.239, 0.285), ray.y);

  // March along the ray. The field value is roughly the distance to the surface, so step by
  // it (doubled, to arrive in fewer steps) until it gets small.
  vec3 p = camera;
  for (int i = 0; i < 64; i++) {
    float dist = 2.0 * field(p);
    p += dist * ray;
    if (dist < 0.05) {
      // A hit: the mirror shows the panorama in the direction the ray bounces off.
      color = panorama(reflect(ray, normalize(fieldGradient(p))));
      break;
    }
  }

  // The photo itself, as an inset square at the top right with softened edges.
  vec2 uv = (fragCoord / iResolution - vec2(0.61, 0.6)) * 2.96961;
  vec2 inside = smoothstep(0.0, 0.01, uv) * smoothstep(0.0, 0.01, 1.0 - uv);
  color = mix(color, texture(iTexture0, uv).rgb, inside.x * inside.y);

  fragColor = vec4(color, 1.0);
}
